// Turns ALAN's prompt and memories into a module the Netlify functions import.
// (Files read from disk at run time are not bundled with a function; imports are.)
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const read = (name) => readFileSync(join(root, "prompts", name), "utf8");
mkdirSync(join(root, "netlify", "lib"), { recursive: true });
writeFileSync(
  join(root, "netlify", "lib", "texts.gen.mjs"),
  "// Generated by scripts/netlify-texts.mjs from prompts/. Do not edit.\n" +
    `export const SYSTEM = ${JSON.stringify(read("system.pl.txt"))};\n` +
    `export const MEMORIES = ${JSON.stringify(read("memories.pl.md"))};\n` +
    `export const TRAVEL = ${JSON.stringify(read("travel.pl.md"))};\n`,
);
console.log("netlify/lib/texts.gen.mjs written");
